// MDDBServer is the server API for MDDB service.
// All implementations must embed UnimplementedMDDBServer
// for forward compatibility.
//
// MDDB Service - gRPC API for Markdown Database
type MDDBServer interface {
	// Add or update a document
	Add(context.Context, *AddRequest) (*Document, error)
	// Add or update multiple documents in a single transaction (batch)
	AddBatch(context.Context, *AddBatchRequest) (*AddBatchResponse, error)
	// Delete multiple documents in a single transaction (batch)
	DeleteBatch(context.Context, *DeleteBatchRequest) (*DeleteBatchResponse, error)
	// Update multiple documents in a single transaction (batch)
	UpdateBatch(context.Context, *UpdateBatchRequest) (*UpdateBatchResponse, error)
	// Get a document by key and language
	Get(context.Context, *GetRequest) (*Document, error)
	// Search documents with filters
	Search(context.Context, *SearchRequest) (*SearchResponse, error)
	// Export documents (streaming)
	Export(*ExportRequest, grpc.ServerStreamingServer[ExportChunk]) error
	// Create database backup
	Backup(context.Context, *BackupRequest) (*BackupResponse, error)
	// Restore database from backup
	Restore(context.Context, *RestoreRequest) (*RestoreResponse, error)
	// Truncate revision history
	Truncate(context.Context, *TruncateRequest) (*TruncateResponse, error)
	// Get server statistics
	Stats(context.Context, *StatsRequest) (*StatsResponse, error)
	// Vector/semantic search using embeddings
	VectorSearch(context.Context, *VectorSearchRequest) (*VectorSearchResponse, error)
	// Reindex embeddings for a collection
	VectorReindex(context.Context, *VectorReindexRequest) (*VectorReindexResponse, error)
	// Get vector/embedding statistics
	VectorStats(context.Context, *VectorStatsRequest) (*VectorStatsResponse, error)
	// Geo search: documents within N meters of a (lat, lng) point
	GeoSearch(context.Context, *GeoSearchRequest) (*GeoSearchResponse, error)
	// Geo within: documents inside an axis-aligned bounding box
	GeoWithin(context.Context, *GeoWithinRequest) (*GeoWithinResponse, error)
	// Force-rebuild the in-memory geo R-tree from BoltDB
	GeoReindex(context.Context, *GeoReindexRequest) (*GeoReindexResponse, error)
	// Geo index statistics
	GeoStats(context.Context, *GeoStatsRequest) (*GeoStatsResponse, error)
	// Encode a (lat, lng) pair into a geohash string
	GeoEncode(context.Context, *GeoEncodeRequest) (*GeoEncodeResponse, error)
	// Decode a geohash back to (lat, lng) centroid + bbox
	GeoDecode(context.Context, *GeoDecodeRequest) (*GeoDecodeResponse, error)
	// Import document from URL
	ImportURL(context.Context, *ImportURLRequest) (*Document, error)
	// Set TTL on a document
	SetTTL(context.Context, *SetTTLRequest) (*Document, error)
	// Full-text search
	FTS(context.Context, *FTSRequest) (*FTSResponse, error)
	// Reindex FTS for a collection (re-applies language-aware stemming)
	FTSReindex(context.Context, *FTSReindexRequest) (*FTSReindexResponse, error)
	// List supported FTS languages
	FTSLanguages(context.Context, *FTSLanguagesRequest) (*FTSLanguagesResponse, error)
	// Hybrid search (combines FTS + vector search)
	HybridSearch(context.Context, *HybridSearchRequest) (*HybridSearchResponse, error)
	// Register a webhook
	RegisterWebhook(context.Context, *RegisterWebhookRequest) (*WebhookProto, error)
	// List webhooks
	ListWebhooks(context.Context, *ListWebhooksRequest) (*ListWebhooksResponse, error)
	// Delete a webhook
	DeleteWebhook(context.Context, *DeleteWebhookRequest) (*DeleteWebhookResponse, error)
	// Set JSON Schema for a collection's metadata validation
	SetSchema(context.Context, *SetSchemaRequest) (*SetSchemaResponse, error)
	// Get JSON Schema for a collection
	GetSchema(context.Context, *GetSchemaRequest) (*GetSchemaResponse, error)
	// Delete JSON Schema for a collection (disables validation)
	DeleteSchema(context.Context, *DeleteSchemaRequest) (*DeleteSchemaResponse, error)
	// List all collection schemas
	ListSchemas(context.Context, *ListSchemasRequest) (*ListSchemasResponse, error)
	// Validate document metadata against collection schema
	ValidateDocument(context.Context, *ValidateDocumentRequest) (*ValidateDocumentResponse, error)
	// Partial document update (meta and/or content independently)
	UpdateDocument(context.Context, *UpdateDocumentRequest) (*Document, error)
	// Get document metadata only (without content)
	GetDocumentMeta(context.Context, *GetDocumentMetaRequest) (*GetDocumentMetaResponse, error)
	// Zero-shot document classification using embedding similarity
	Classify(context.Context, *ClassifyRequest) (*ClassifyResponse, error)
	// SearchAdvisor measures a collection and recommends how to search it
	// (SRCH-010), so a client picks an algorithm from evidence rather than from
	// the names. Added for gRPC parity: the HTTP endpoint and the MCP tool
	// already existed, and the Python client speaks gRPC.
	SearchAdvisor(context.Context, *SearchAdvisorRequest) (*SearchAdvisorResponse, error)
	// Queued embedding and metadata work for a collection, or for the server
	// when collection is empty (GO-042): is what was just written searchable yet?
	GetIndexingStatus(context.Context, *IndexingStatusRequest) (*IndexingStatusResponse, error)
	// Everything about one symbol in a code collection (CODE-008): its
	// definitions, references, callers, callees, tests and siblings.
	CodeSymbol(context.Context, *CodeSymbolRequest) (*CodeSymbolResponse, error)
	// Retrieval evaluation (SRCH-019): score search configurations on the
	// collection's evaluation set, and manage that set.
	RunEval(context.Context, *RunEvalRequest) (*RunEvalResponse, error)
	AddEvalQuery(context.Context, *AddEvalQueryRequest) (*EvalQueryProto, error)
	ListEvalQueries(context.Context, *ListEvalQueriesRequest) (*ListEvalQueriesResponse, error)
	DeleteEvalQuery(context.Context, *DeleteEvalQueryRequest) (*DeleteEvalQueryResponse, error)
	// Tokens returned and avoided by retrieval over a window of days (AGT-004).
	GetGain(context.Context, *GetGainRequest) (*GetGainResponse, error)
	// Delete, merge metadata into, or set the TTL of every document a metadata
	// filter matches (GO-045). Use dry_run first.
	DeleteWhere(context.Context, *WhereRequest) (*WhereResponse, error)
	UpdateWhere(context.Context, *WhereRequest) (*WhereResponse, error)
	SetTTLWhere(context.Context, *WhereRequest) (*WhereResponse, error)
	// Delete a single document
	DeleteDocument(context.Context, *DeleteDocumentRequest) (*DeleteDocumentResponse, error)
	// Delete an entire collection
	DeleteCollection(context.Context, *DeleteCollectionRequest) (*DeleteCollectionResponse, error)
	// List synonyms for a collection
	ListSynonyms(context.Context, *ListSynonymsRequest) (*ListSynonymsResponse, error)
	// Add a synonym mapping
	AddSynonym(context.Context, *AddSynonymRequest) (*AddSynonymResponse, error)
	// Delete a synonym mapping
	DeleteSynonym(context.Context, *DeleteSynonymRequest) (*DeleteSynonymResponse, error)
	// List stop words for a collection
	ListStopwords(context.Context, *ListStopwordsRequest) (*ListStopwordsResponse, error)
	// Add custom stop words
	AddStopwords(context.Context, *AddStopwordsRequest) (*AddStopwordsResponse, error)
	// Delete custom stop words
	DeleteStopwords(context.Context, *DeleteStopwordsRequest) (*DeleteStopwordsResponse, error)
	// Get all unique metadata keys and values for a collection
	GetMetaKeys(context.Context, *GetMetaKeysRequest) (*GetMetaKeysResponse, error)
	// Get collection checksum (integrity hash)
	GetChecksum(context.Context, *GetChecksumRequest) (*GetChecksumResponse, error)
	// List automation rules
	ListAutomation(context.Context, *ListAutomationRequest) (*ListAutomationResponse, error)
	// Create an automation rule
	CreateAutomation(context.Context, *CreateAutomationRequest) (*AutomationRuleProto, error)
	// Get an automation rule by ID
	GetAutomation(context.Context, *GetAutomationRequest) (*AutomationRuleProto, error)
	// Update an automation rule
	UpdateAutomation(context.Context, *UpdateAutomationRequest) (*AutomationRuleProto, error)
	// Delete an automation rule
	DeleteAutomation(context.Context, *DeleteAutomationRequest) (*DeleteAutomationResponse, error)
	// Test an automation trigger (dry run)
	TestAutomation(context.Context, *TestAutomationRequest) (*TestAutomationResponse, error)
	// Get automation execution logs
	GetAutomationLogs(context.Context, *GetAutomationLogsRequest) (*GetAutomationLogsResponse, error)
	// Get collection configuration
	GetCollectionConfig(context.Context, *GetCollectionConfigRequest) (*GetCollectionConfigResponse, error)
	// Set collection configuration
	SetCollectionConfig(context.Context, *SetCollectionConfigRequest) (*SetCollectionConfigResponse, error)
	// List all collection configurations
	ListCollectionConfigs(context.Context, *ListCollectionConfigsRequest) (*ListCollectionConfigsResponse, error)
	// Cross-collection vector search
	CrossSearch(context.Context, *CrossSearchRequest) (*CrossSearchResponse, error)
	// Find duplicate documents in a collection
	FindDuplicates(context.Context, *FindDuplicatesRequest) (*FindDuplicatesResponse, error)
	// Bulk ingest documents with URL key derivation, frontmatter extraction, and deduplication
	Ingest(context.Context, *IngestRequest) (*IngestResponse, error)
	// List revision history for a document
	ListRevisions(context.Context, *ListRevisionsRequest) (*ListRevisionsResponse, error)
	// Restore a document from a specific revision
	RestoreRevision(context.Context, *RestoreRevisionRequest) (*Document, error)
	// Query temporal events for a specific document
	TemporalQuery(context.Context, *TemporalQueryRequest) (*TemporalQueryResponse, error)
	// Get hot (most accessed) documents in a collection
	TemporalHot(context.Context, *TemporalHotRequest) (*TemporalHotResponse, error)
	// Get spell correction suggestions for a text string
	SpellSuggest(context.Context, *SpellSuggestRequest) (*SpellSuggestResponse, error)
	// Apply best spell corrections to a text string
	SpellCleanup(context.Context, *SpellCleanupRequest) (*SpellCleanupResponse, error)
	// (v2.9.14+) Curation: list rules scoped to a collection (or all)
	ListCurationRules(context.Context, *ListCurationRulesRequest) (*ListCurationRulesResponse, error)
	// (v2.9.14+) Curation: create a new rule
	CreateCurationRule(context.Context, *CreateCurationRuleRequest) (*CurationRuleProto, error)
	// (v2.9.14+) Curation: replace an existing rule by id
	UpdateCurationRule(context.Context, *UpdateCurationRuleRequest) (*CurationRuleProto, error)
	// (v2.9.14+) Curation: remove a rule by id
	DeleteCurationRule(context.Context, *DeleteCurationRuleRequest) (*DeleteCurationRuleResponse, error)
	// (v2.19.0+) Run a cron rule's sync or backup now, through the code its
	// schedule fires; returns the run's job id (#377).
	RunAutomation(context.Context, *RunAutomationRequest) (*RunAutomationResponse, error)
	// (v2.19.0+, #378) Corpus packs (AGT-005), as /v1/corpus/*. Listing reads
	// every collection in the caller's tenant; the rest need admin.
	ListCorpusPacks(context.Context, *ListCorpusPacksRequest) (*ListCorpusPacksResponse, error)
	// The pack as a stream of chunks, or an https URL the server fetches
	// through its SSRF guard, in the first message.
	InstallCorpusPack(grpc.ClientStreamingServer[InstallCorpusPackRequest, InstallCorpusPackResponse]) error
	RemoveCorpusPack(context.Context, *RemoveCorpusPackRequest) (*RemoveCorpusPackResponse, error)
	// The pack of a collection, streamed as tar.zst chunks.
	BuildCorpusPack(*BuildCorpusPackRequest, grpc.ServerStreamingServer[CorpusPackChunk]) error
	// (v2.19.0+, GO-049) Module switches, as /v1/features. Any authenticated
	// caller lists them; SetFeature needs a global administrator. A method of
	// a disabled module answers FAILED_PRECONDITION "feature disabled: <name>".
	ListFeatures(context.Context, *ListFeaturesRequest) (*ListFeaturesResponse, error)
	// FAILED_PRECONDITION when MDDB_FEATURES_FORCE_OFF locks the module,
	// NOT_FOUND for a name outside the registry.
	SetFeature(context.Context, *SetFeatureRequest) (*SetFeatureResponse, error)
	// (v2.19.0+, #403) Chat scenarios, as /v1/chat/scenarios. Reads need read
	// permission on the collections a scenario allows; writes need admin.
	ListChatScenarios(context.Context, *ListChatScenariosRequest) (*ListChatScenariosResponse, error)
	GetChatScenario(context.Context, *GetChatScenarioRequest) (*ChatScenarioProto, error)
	// Creates or replaces the scenario named in it; bumps the version counter.
	PutChatScenario(context.Context, *PutChatScenarioRequest) (*PutChatScenarioResponse, error)
	DeleteChatScenario(context.Context, *DeleteChatScenarioRequest) (*DeleteChatScenarioResponse, error)
	// The composed system prompt: operator prompt, guardrails, off-topic
	// clause, the scenario's skills in order (#404), style clause, then each
	// allowed collection's responsePrompt — with its size.
	GetChatScenarioPrompt(context.Context, *GetChatScenarioPromptRequest) (*GetChatScenarioPromptResponse, error)
	// ---- (v2.19.0+, #404) Chat skills, as /v1/chat/skills: reusable SKILL.md
	// instruction blocks that scenarios attach by name. Admin only, reads
	// included. A change bumps the chat scenarios' version counter.
	// Every skill, without contents.
	ListChatSkills(context.Context, *ListChatSkillsRequest) (*ListChatSkillsResponse, error)
	// The current version, or a kept earlier one.
	GetChatSkill(context.Context, *GetChatSkillRequest) (*ChatSkillProto, error)
	// Creates the skill or stores a new version of it.
	PutChatSkill(context.Context, *PutChatSkillRequest) (*PutChatSkillResponse, error)
	// FAILED_PRECONDITION while a scenario attaches the skill.
	DeleteChatSkill(context.Context, *DeleteChatSkillRequest) (*DeleteChatSkillResponse, error)
	// A preview of the SKILL.md at an https URL (fetched through the SSRF
	// guard) or of pasted text. Stores nothing.
	ImportChatSkill(context.Context, *ImportChatSkillRequest) (*ChatSkillPreviewProto, error)
	// Fetches the skill's source again: a preview, stored with confirm.
	UpdateChatSkill(context.Context, *UpdateChatSkillRequest) (*UpdateChatSkillResponse, error)
	// The scenarios attaching the skill.
	GetChatSkillUsedBy(context.Context, *GetChatSkillUsedByRequest) (*GetChatSkillUsedByResponse, error)
	// ---- (v2.19.0+, MCP-005) External MCP servers of the chat, as
	// /v1/chat/mcp-secrets and /v1/chat/mcp. Secrets are write-only: no call
	// returns a value. Admin, except CallChatMcpTool.
	// The secrets: name, header, set and the scenarios using each.
	ListChatMcpSecrets(context.Context, *ListChatMcpSecretsRequest) (*ListChatMcpSecretsResponse, error)
	// Sets or replaces a secret.
	PutChatMcpSecret(context.Context, *PutChatMcpSecretRequest) (*PutChatMcpSecretResponse, error)
	// FAILED_PRECONDITION while a scenario uses the secret.
	DeleteChatMcpSecret(context.Context, *DeleteChatMcpSecretRequest) (*DeleteChatMcpSecretResponse, error)
	// Connects to a server (https, SSRF-guarded) and lists its tools with their
	// annotations. FAILED_PRECONDITION while the chatExternalMcp feature is off.
	InspectChatMcpServer(context.Context, *InspectChatMcpServerRequest) (*InspectChatMcpServerResponse, error)
	// Calls an allowed, read-only tool of a scenario's server for mddb-chat,
	// which never sees the credential. Needs read on the scenario.
	CallChatMcpTool(context.Context, *CallChatMcpToolRequest) (*CallChatMcpToolResponse, error)
	// ---- (v2.19.0+, #405) Persistent per-user chat conversations, as
	// /v1/chat/conversations. The caller is the host application; every call
	// names the user (sub), and a conversation of another sub is NOT_FOUND.
	// Permission is on the chat collection of the caller's tenant: read for
	// List/Get/Export, write for the rest.
	CreateChatConversation(context.Context, *CreateChatConversationRequest) (*ChatConversationProto, error)
	// One page of a user's conversations, newest first, without messages.
	ListChatConversations(context.Context, *ListChatConversationsRequest) (*ListChatConversationsResponse, error)
	// A conversation with its last `limit` messages (all when 0).
	GetChatConversation(context.Context, *GetChatConversationRequest) (*ChatConversationProto, error)
	// Returns the conversation holding only the messages added, with their ids.
	AppendChatMessages(context.Context, *AppendChatMessagesRequest) (*ChatConversationProto, error)
	EndChatConversation(context.Context, *EndChatConversationRequest) (*ChatConversationProto, error)
	DeleteChatConversation(context.Context, *DeleteChatConversationRequest) (*DeleteChatConversationResponse, error)
	// Everything of one user (GDPR erasure).
	DeleteChatConversationsForUser(context.Context, *DeleteChatConversationsForUserRequest) (*DeleteChatConversationsForUserResponse, error)
	// Everything of one user (GDPR export): one conversation per message,
	// newest first, each with all its messages.
	ExportChatConversations(*ExportChatConversationsRequest, grpc.ServerStreamingServer[ChatConversationProto]) error
	mustEmbedUnimplementedMDDBServer()
}

